// Generated by wellfed-dashboard's `bindings` test from the page's Rust views.
// Do not edit: change the Rust types, then run
// UPDATE_BINDINGS=1 cargo test -p wellfed-dashboard bindings

export type JsonValue = number | string | boolean | Array<JsonValue> | { [key in string]: JsonValue } | null;

/**
 * How a command went, as its record and the history keep it.
 */
export type Outcome = "running" | "pass" | "stopped" | "ended";

/**
 * Where one of a command's steps stands; the page colours its rows by it.
 */
export type StepState = "pending" | "running" | "done" | "failed" | "skipped";

export type Step = { label: string, state: StepState, 
/**
 * When it began running and when it finished, for the page's timers.
 */
started?: number | null, finished?: number | null, };

/**
 * What a progress count counts.
 */
export type Unit = "bytes" | "sectors";

export type Progress = { done: number, total: number, unit: Unit, 
/**
 * Rate baseline: when and at which count this count series began.
 */
since: number, since_done: number, at: number, };

export type FlashTool = { path: string, sha256: string, };

/**
 * The bench command a progress record belongs to, by its CLI name. A
 * history line naming a command this bench no longer has does not read,
 * and the page skips it.
 */
export type BenchCommand = "status" | "off" | "on" | "capture" | "press" | "boot" | "loader" | "transients" | "dump" | "flash-prepare" | "flash-execute" | "give-way-prepare" | "give-way-execute" | "stock-prepare" | "stock-execute" | "ota" | "itest" | "stock-ota" | "install" | "restore-stock";

export type HistoryEntry = { command: BenchCommand, name: string | null, started: number, finished: number | null, outcome: Outcome, error: string | null, next?: string | null, };

/**
 * A relay's state as the board last acknowledged or reported it, and when.
 */
export type RelayState = { on: boolean, at: number, };

/**
 * How much of the suite a run takes on; each tier includes the cheaper ones.
 */
export type Tier = "smoke" | "standard" | "soak";

/**
 * A session flag a scenario needs, and why.
 */
export type Requirement = { flag: string, why: string, };

/**
 * One scenario as the page lists it: what it checks and what it needs.
 */
export type CatalogEntry = { name: string, about: string, 
/**
 * The cheapest tier that runs it.
 */
tier: Tier, needs: Array<Requirement>, 
/**
 * Installs the build under test; every other scenario needs it.
 */
baseline: boolean, };

export type Evidence = "physical";

export type ScenarioVerdict = "pass" | "fail" | "skip";

export type ScenarioRecord = { scenario: string, verdict: ScenarioVerdict, reason: string | null, seconds: number, };

export type RunRecord = { name: string, 
/**
 * Always `physical`: these verdicts come from the feeder on the bench.
 */
evidence: Evidence, scenarios: Array<ScenarioRecord>, 
/**
 * Why the suite stopped when the feeder went quiet; it then needs UART recovery.
 */
silent: string | null, 
/**
 * Root-relative UART capture directories, in order.
 */
captures: Array<string>, };

export type Capture = { 
/**
 * Root-relative capture directory.
 */
path: string, seconds: number, started: number, };

export type Transfer = { 
/**
 * Root-relative session directory.
 */
path: string, tx: number, rx: number, started: number | null, };

export type Current = { pid: number, command: BenchCommand, name: string | null, started: number, finished: number | null, outcome: Outcome, error: string | null, steps: Array<Step>, progress: Progress | null, capture: Capture | null, transfer: Transfer | null, relay: { [key in string]: boolean }, lines: Array<string>, 
/**
 * The command to run after review, such as a prepared plan's execute.
 */
next?: string | null, flash_tool?: FlashTool | null, };

/**
 * Everything a reader shows of the bench right now.
 */
export type BenchState = { 
/**
 * The bench host's clock when the state was read, so a reader's
 * timers agree with it.
 */
now: number, server: ServerView, 
/**
 * The running job, or else the last one to finish.
 */
job: JobView | null, 
/**
 * What the running job asks the person at the bench, until it is
 * answered, cancelled or the job ends.
 */
prompt: PendingPrompt | null, 
/**
 * Every child process a job has running, as it starts and exits.
 */
activity: Array<Activity>, uart: Uart, 
/**
 * By channel, `"1"` to `"4"`: what the board last answered or
 * acknowledged. The server holds the board, so nothing else switches
 * a relay between reads, except the board's own front buttons.
 */
relays: { [key in string]: RelayState }, 
/**
 * The owner's device API session and what it last read.
 */
feeder: FeederView, 
/**
 * The receive-only capture's newest lines and the records parsed
 * from them.
 */
capture: CaptureView, 
/**
 * Which build the bench believes each bank holds.
 */
banks: Ledger, 
/**
 * What the operator's notes say now.
 */
operator: Operator, };

/**
 * The server process.
 */
export type ServerView = { pid: number, started: number, phase: Phase, 
/**
 * Whether the configured UART adapter's port exists, as the server
 * last looked: at its start, after every job and with every idle
 * relay read. The relay board's port is the server's own.
 */
uart_port: boolean, 
/**
 * A stop asked for during a UART write, held until the write's job
 * ends; meanwhile the server takes no new job.
 */
stopping: DeferredStop | null, };

/**
 * Whether the server takes jobs.
 */
export type Phase = "serving" | "stopping";

/**
 * A SIGTERM or hangup that came during a UART write: the server stops
 * once `job` has ended.
 */
export type DeferredStop = { 
/**
 * The job that was writing.
 */
job: number | null, 
/**
 * When the stop was asked for.
 */
since: number, };

/**
 * One job: what was asked, how far it is, and how it ended.
 */
export type JobView = { id: number, 
/**
 * The command as the client asked for it, such as `dump unit-01`.
 */
label: string, 
/**
 * Root-relative: the file its output is kept in.
 */
log: string, accepted: number, 
/**
 * The command's own record, from its first step on.
 */
record: Current | null, 
/**
 * The labels of the next few steps still pending.
 */
upcoming: Array<string>, cancel: CancelState, end: JobEnd | null, };

/**
 * A question a job waits on: `wellfed install` asks it, and whoever
 * answers (the page, `wellfed-bench answer`, an agent) names
 * its `seq`. The number is the job's own count of its questions, from 1,
 * so an answer meant for one question never lands on the next.
 */
export type PendingPrompt = { job: number, seq: number, prompt: Prompt, 
/**
 * The prompt's words, as the installer's terminal shows them.
 */
text: string, expects: Expects, };

/**
 * One question the installer stops at until it is answered.
 */
export type Prompt = { "kind": "set-override", name: string, broker: string, } | { "kind": "restart-feeder" } | { "kind": "recognize-feeder", device: string, address: string, } | { "kind": "setup-mode" } | { "kind": "join-back" } | { "kind": "open-recovery-window" } | { "kind": "key-setup-code", presses: Array<"reset" | "mic" | "dispense" | "lock">, } | { "kind": "press-dispense", purpose: DispensePurpose, };

/**
 * What a Dispense press asked for confirms.
 */
export type DispensePurpose = "enroll-update-key";

/**
 * The kind of answer a prompt takes.
 */
export type Expects = "done" | "yes-no";

/**
 * The person's answer to one prompt.
 */
export type Answer = "done" | "yes" | "no";

/**
 * `POST /jobs/{id}/answer`: the answer to the job's question `seq`.
 */
export type AnswerRequest = { seq: number, answer: Answer, };

/**
 * Why an answer was not passed to the job. Each is refused before
 * anything reaches it, and a refused answer is never held for later: the
 * installer reads answers in order, with no number of their own, so one
 * sent ahead of its question would answer that question unseen.
 */
export type AnswerError = { "refused": "not-running", job: number, } | { "refused": "no-prompt", job: number, } | { "refused": "wrong-seq", job: number, seq: number, pending: number, } | { "refused": "mismatched", name: string, expects: Expects, answer: Answer, };

/**
 * Whether anyone asked the job to stop.
 */
export type CancelState = "none" | "requested";

/**
 * How a job ended: its exit code (0 complete, 1 stopped, 2 a suite's
 * silent feeder) and the error it stopped on.
 */
export type JobEnd = { code: number, error: string | null, finished: number, };

/**
 * One child process a job has running.
 */
export type Activity = { kind: ActivityKind, pid: number, 
/**
 * Its subcommand words, such as `update execute` or `serve`.
 */
label: string, started: number, };

/**
 * What a child is, which decides how a cancel stops it.
 */
export type ActivityKind = "flash" | "build" | "stock" | "install" | "analyzer";

/**
 * What the feeder's UART is doing, for the banner that says not to touch
 * the bench during a write.
 */
export type Uart = { "state": "idle" } | { "state": "capturing", path: string | null, } | { "state": "loader" } | { "state": "writing", done: number, total: number, 
/**
 * Whether this write reports a sector count at all: a give-way
 * and a stock recovery print none, so theirs stays 0 of 0.
 */
counted: boolean, };

/**
 * The owner's device API session, as the server holds it.
 */
export type FeederView = { session: Session, 
/**
 * The last status read, and when.
 */
status: FeederStatus | null, status_at: number | null, clock: ClockView, 
/**
 * The newest event the feeder has recorded, as its status or the
 * last pushed event said.
 */
journal: Journal | null, 
/**
 * Whether the bench hotspot's connection is up, read with nmcli;
 * `None` without a `private/hotspot.json`, or when nmcli failed.
 */
hotspot: boolean | null, 
/**
 * The feeder's newest debug log lines.
 */
log: Array<string>, 
/**
 * Device API sessions open on the feeder besides the server's, at the
 * last status: anything above 0 is a session the bench did not open
 * through the server, which the page and the console warn of.
 */
other_sessions: number, };

/**
 * Where the session stands.
 */
export type Session = { "state": "idle" } | { "state": "unconfigured", error: string, } | { "state": "paused", pause: Pause, } | { "state": "connecting", attempt: number, error: string | null, retry: number | null, } | { "state": "open", address: string, build: string, since: number, };

/**
 * Why the server closed its session.
 */
export type Pause = { "kind": "uart-job", job: number, label: string, } | { "kind": "install" } | { "kind": "stock-ota", job: number, } | { "kind": "stock-install", job: number, } | { "kind": "power-off" } | { "kind": "stopping" };

/**
 * The parts of the feeder's status the page shows.
 */
export type FeederStatus = { 
/**
 * The startup identity, lowercase hex.
 */
build: string, bank: number, uptime_ms: number, boot_count: number, rssi: number, 
/**
 * Unix milliseconds; `None` while the clock is invalid.
 */
clock_ms: number | null, locked: boolean | null, last_event: number | null, sessions: number, };

/**
 * The feeder's clock against the bench host's.
 */
export type ClockView = { 
/**
 * The feeder's clock minus the host's at the last status, in
 * milliseconds; `None` while it is invalid or unread.
 */
skew_ms: number | null, 
/**
 * When the server last set it.
 */
synced_at: number | null, };

/**
 * The newest event the feeder holds.
 */
export type Journal = { seq: number, 
/**
 * The history the number counts in, once an event has named it.
 */
epoch: number | null, from: JournalSource, };

export type JournalSource = "status" | "event";

/**
 * The receive-only capture the server holds while the feeder is idle and
 * powered.
 */
export type CaptureView = { 
/**
 * Root-relative: the segment being written, while one is.
 */
segment: string | null, 
/**
 * Why the capture stopped on its own, until it starts again.
 */
failure: string | null, 
/**
 * The newest UART lines, from this capture or an earlier one.
 */
lines: Array<string>, 
/**
 * The last `PLFW1 start` seen.
 */
start: StartRecord | null, 
/**
 * The last `PLOTA1` record seen.
 */
update: UartRecord | null, };

export type StartRecord = { build: string, bank: number | null, };

export type UartRecord = { line: string, at: number, };

/**
 * The ledger: an entry per bank the bench has evidence for.
 */
export type Ledger = { banks: { [key in Bank]?: Entry }, };

/**
 * A flash bank: 0 is the factory loader's fallback, 1 the application.
 */
export type Bank = "0" | "1";

/**
 * What one bank holds, by whose word, and whether the feeder agrees.
 */
export type Entry = { content: Content, source: Source, 
/**
 * The session name of the job that wrote it.
 */
session: string | null, at: number, check: Check, };

export type Content = { "kind": "build", id: string, } | { "kind": "stock" } | { "kind": "invalid" } | { "kind": "image", sha256: string, } | { "kind": "unknown" };

/**
 * The job result an entry came from.
 */
export type Source = "seed" | "flash-execute" | "give-way" | "ota-confirmed" | "ota-fell-back" | "stock-ota" | "stock-execute" | "itest" | "install";

/**
 * Whether the feeder's own report agrees with the entry.
 */
export type Check = { "state": "unchecked" } | { "state": "confirmed", by: Witness, at: number, } | { "state": "disputed", by: Witness, at: number, seen: Content, };

/**
 * What reported a bank's build.
 */
export type Witness = "banner" | "status";

/**
 * What the notes say now.
 */
export type Operator = { step: string | null, next: Array<string>, timers: Array<Timer>, 
/**
 * By card, in the order each card was first noted.
 */
evidence: Array<[string, Array<CardEvidence>]>, };

/**
 * A timer still running or run out, as the notes leave it.
 */
export type Timer = { label: string, started: number, due: number, 
/**
 * The end of the window an expectation may be seen in.
 */
until: number, expect: Expect | null, state: TimerState, };

/**
 * What a timer waits for.
 */
export type Expect = { "on": "line", text: string, } | { "on": "event", kind: string, };

/**
 * Whether a timer's expectation has been settled.
 */
export type TimerState = { "state": "waiting" } | { "state": "seen", at: number, line: string, } | { "state": "missed", at: number, };

/**
 * One card's evidence, in the order it was noted.
 */
export type CardEvidence = { at: number, verdict: Verdict, text: string, path: string | null, };

export type Verdict = "pass" | "fail";

/**
 * A file's size, modification time and printable tail: a capture's
 * serial-rx.bin or a run's server log.
 */
export type TailView = { 
/**
 * Root-relative: the capture directory, or the file itself.
 */
path: string, bytes: number, modified: number | null, tail: Array<string>, };

export type EvidenceView = { 
/**
 * Newest first.
 */
history: Array<HistoryEntry>, 
/**
 * The latest capture's output.
 */
rx: TailView | null, script: ScriptView | null, 
/**
 * The QA firmware's guided run in the latest capture.
 */
qa: QaView | null, };

/**
 * One instruction, shown from `at` seconds after the anchor arrived.
 */
export type ScriptStep = { at: number, text: string, };

/**
 * The optional operator script: timed steps from an anchor in a capture.
 */
export type ScriptView = { title: string, capture: string, steps: Array<ScriptStep>, anchor: string, 
/**
 * When the anchor arrived; `None` until it has.
 */
started: number | null, capture_exists: boolean, };

export type QaState = "waiting" | "running" | "pass" | "fail";

export type QaAsk = "press" | "look" | "listen";

export type QaPromptView = { ask: QaAsk, 
/**
 * A button (`reset`), a pin (`PA0`) or a tune (`test`).
 */
target: string, 
/**
 * When the prompt arrived, if the capture's events place it.
 */
asked: number | null, };

export type QaItemView = { ask: QaAsk, target: string, passed: boolean, 
/**
 * The firmware's reason when it failed: `timeout`, `wrong`, `no`…
 */
reason: string | null, };

export type QaCheckView = { check: "optics" | "power" | "buttons" | "indicators" | "speaker", state: QaState, items: Array<QaItemView>, };

/**
 * The newest QA run in the latest capture.
 */
export type QaView = { 
/**
 * Root-relative capture directory.
 */
capture: string, 
/**
 * All five checks, in sequence order.
 */
checks: Array<QaCheckView>, 
/**
 * The question waiting for an answer, if any.
 */
prompt: QaPromptView | null, 
/**
 * The result line's overall status, once it has arrived.
 */
passed: boolean | null, 
/**
 * Records the parser could not read; the audit would refuse the run.
 */
unreadable: number, };

/**
 * `/api/sessions`: recent session names with the evidence each one has.
 */
export type Sessions = { sessions: Array<SessionRow>, };

/**
 * The evidence parts a session name can have, in the order a session
 * makes them.
 */
export type Part = "loader" | "bounded" | "full" | "inspect" | "plan" | "execute" | "boot";

export type SessionRow = { name: string, modified: number, 
/**
 * The evidence parts found.
 */
parts: Array<Part>, 
/**
 * The furthest part's state, in the report's own words (`read complete`).
 */
outcome: string, };

/**
 * `/api/sessions/{name}`: one session's evidence, plan and next command.
 */
export type SessionView = { name: string, parts: Array<PartView>, 
/**
 * The reviewed command that follows, if one was recorded.
 */
next: string | null, };

export type PartView = { kind: Part, path: string, modified: number | null, 
/**
 * Execute only: the serial bytes it exchanged.
 */
serial: Serial | null, } & ({ "plan": JsonValue | null } | { "report": JsonValue | null });

/**
 * A plan's summary, or any other part's report (`null` when it has none).
 */
export type PartDetail = { "plan": JsonValue | null } | { "report": JsonValue | null };

export type Serial = { tx: number, rx: number, };

/**
 * `/api/health`: ports, the flash client and the image the feeder last
 * booted.
 */
export type HealthView = { 
/**
 * Root-relative `bench.json`.
 */
config: string, config_ok: boolean, ports: Ports, flash_tool: FlashToolView, installed: Installed | null, };

/**
 * Whether each configured path exists, or why the config does not read.
 */
export type Ports = { relay_port: boolean, uart_port: boolean, baseline: boolean, rom_report: boolean, } | { error: string, };

export type FlashToolView = { path: string, sha256: string | null, present: boolean, };

/**
 * The newest replacement-firmware start banner in a capture.
 */
export type Installed = { capture: string, 
/**
 * When that capture was last written.
 */
at: number, build: string | null, bank: string | null, role: Role, };

export type Role = "normal" | "recovery";

export type RunRow = { 
/**
 * When the record was written: the run's end.
 */
modified: number, name: string, 
/**
 * Always `physical`: these verdicts come from the feeder on the bench.
 */
evidence: Evidence, scenarios: Array<ScenarioRecord>, 
/**
 * Why the suite stopped when the feeder went quiet; it then needs UART recovery.
 */
silent: string | null, 
/**
 * Root-relative UART capture directories, in order.
 */
captures: Array<string>, };

export type Failure = { run: string, reason: string | null, };

/**
 * One scenario across the runs that took it on.
 */
export type ScenarioStats = { scenario: string, pass: number, fail: number, skip: number, 
/**
 * Median time of its passing runs.
 */
median_seconds: number | null, last_failure: Failure | null, 
/**
 * Newest first over the last [`HISTORY_RUNS`] runs; `null` where a run
 * did not include it.
 */
history: Array<ScenarioVerdict | null>, 
/**
 * Pass and fail alternations in that history, skips aside: a scenario
 * that flips is flaky, or its subject is.
 */
flips: number, };

/**
 * `/api/tests`: the catalog, runs newest first, and each scenario's record.
 */
export type TestsView = { catalog: Array<CatalogEntry>, runs: Array<RunRow>, 
/**
 * Catalog order, then any scenario only older records name.
 */
scenarios: Array<ScenarioStats>, };

/**
 * `/api/tests/{name}`: one run's record with its evidence tails.
 */
export type RunView = { modified: number | null, 
/**
 * The tails of the record's captures that lie inside `private/captures/`.
 */
capture_tails: Array<TailView>, 
/**
 * `NAME-servers.log`: what `wellfed-stock` and its helpers printed.
 */
servers: TailView | null, name: string, 
/**
 * Always `physical`: these verdicts come from the feeder on the bench.
 */
evidence: Evidence, scenarios: Array<ScenarioRecord>, 
/**
 * Why the suite stopped when the feeder went quiet; it then needs UART recovery.
 */
silent: string | null, 
/**
 * Root-relative UART capture directories, in order.
 */
captures: Array<string>, };

export type StockView = { "server": "unconfigured", config: string, error: string, } | { "server": "down", address: string, error: string, } | { "server": "up", address: string, 
/**
 * The server's own session with its broker.
 */
broker_connected: boolean, 
/**
 * Stock's telemetry is current.
 */
stock_online: boolean, 
/**
 * The version stock last reported, as it sent it.
 */
stock_version: string | null, };
